  .execute('summarizerB', (state) => ({ documentText: state.documentB }), {
    node: 'summarizer',
  })
  .execute('summarizerC', (state) => ({ documentText: state.documentC }), {
    node: 'summarizer',
  })
  // Waits for all three, then merges
  .execute('merger', (state) => ({
    summaryA: state.summarizerAResult.summaryText,
    summaryB: state.summarizerBResult.summaryText,
    summaryC: state.summarizerCResult.summaryText,
