>()
  .node('summarizer', 'documentText:string -> summaryText:string(max 200)')
  .node('reportMerger', 'summaries:string[] -> finalReport:string')
  // These three run in parallel — each depends only on its own document input
  .execute('summarizerOne', (state) => ({ documentText: state.documentOneText }), {
