  const reasoning = typeof prediction?.reasoning === 'string' ? prediction.reasoning : '';
  const brevity =
    reasoning.length <= 60 ? 1 : reasoning.length <= 120 ? 0.5 : 0.1;
  return { accuracy, brevity };
};

const result = await optimize(classifier, train, metric, {
  studentAI: student,
  teacherAI: teacher,
  numTrials: 16,
  minibatch: true,
  minibatchSize: 8,
  earlyStoppingTrials: 5,
  validationExamples: validation,
  maxMetricCalls: 250,
});

// pick your preferred trade-off from the Pareto front, or just use the default
for (const point of result.paretoFront) {
  console.log(point.scores, point.configuration);
}

classifier.applyOptimization(result.optimizedProgram!);
console.log(JSON.stringify(result.optimizedProgram)); // persist for reuse
```

Key points:
- Returning `{ accuracy, brevity }` (instead of a single number) tells GEPA to treat this as multi-objective and build a Pareto front, rather than collapsing to one score.
- `accuracy` checks the label match; `brevity` rewards shorter `reasoning` output — tune the length thresholds to your desired output size.
- `result.paretoFront` gives you multiple candidates at different accuracy/brevity trade-offs if you want to inspect options instead of trusting the default pick.
- Keep `train`/`validation` disjoint (200 examples ≈ 160/40 split is reasonable) so the selected candidate isn't overfit.

Here's the sketch — `authorizeToolCall` on the MCP client is the built-in gate for side-effecting tools:

```ts
import {
  agent,
  ai,
  AxMCPClient,
  AxMCPStreamableHTTPTransport,
  axMCPBearerAuthentication,
} from '@ax-llm/ax';

const llm = ai({ name: 'openai', apiKey: process.env.OPENAI_APIKEY! });

const transport = new AxMCPStreamableHTTPTransport(
  'https://mcp.example.com/mcp',
  {
    authentication: axMCPBearerAuthentication(
      () => process.env.MCP_ACCESS_TOKEN!
    ),
  }
);

const remote = new AxMCPClient(transport, {
  namespace: 'ops',
  // Gate runs before any side-effecting tool executes.
  authorizeToolCall: async ({ tool, args }) => {
    const isWrite =
      tool.annotations?.destructiveHint === true ||
      tool.annotations?.readOnlyHint === false;

    if (!isWrite) return true;

    return await requestHumanApproval(tool.name, args);
  },
});

const assistant = agent('query:string -> answer:string', {
  ai: llm,
  mcp: [remote],
  contextFields: [],
});

const result = await assistant.forward(llm, {
  query: 'Update the ticket status to resolved',
});
console.log(result.answer);
```

Key points:

- Attach the MCP client via `mcp: [...]`, not `functions` — that preserves task/resource/notification handling and keeps the tool's identity for authorization.
- `authorizeToolCall` on `AxMCPClient` is called before every tool invocation from that client; return `false`/throw to block it. Prefer checking the server's own `tool.annotations` (`destructiveHint`, `readOnlyHint`) rather than guessing from the tool name, since the server declares this.
- `requestHumanApproval` is your own function — e.g. prompt in a CLI, post to Slack and await a response, or check a policy service. Keep it fast/async since it blocks the tool call.
- If you want a generic authorization check that isn't per-client, you can instead wrap `authorizeToolCall` around a shared policy function reused across multiple `AxMCPClient` instances.

For an existing project, I'd first run `docs.inspectCatalog()` (or your client's equivalent) once to see what `annotations` the real server actually sets — some servers don't populate `destructiveHint`/`readOnlyHint` reliably, in which case you'd need an explicit allowlist of write tool names instead.

