For per-customer usage across all agents, use the process-wide `axGlobals.onUsage` observer with `usageContext` — not `getUsage()`, which is per-instance only. For function calls, use `onFunctionCall` on each agent.

```typescript
import { axGlobals } from '@ax-llm/ax';

// Register once, at app startup — process-wide observer
axGlobals.onUsage = (event) => {
  // Must be synchronous/non-blocking: enqueue, don't await DB/network work here
  usageQueue.enqueue(event);
};

// Somewhere durable, drain the queue:
// event: { operation, ai, model, tokens, streaming, context, ... }
async function persistUsageEvent(event) {
  await db.usageLog.insert({
    tenantId: event.context?.tenantId,
    userId: event.context?.userId,
    runId: event.context?.runId,
    feature: event.context?.feature,
    model: event.model,
    promptTokens: event.tokens.promptTokens,
    completionTokens: event.tokens.completionTokens,
