import { Agent, routeAgentRequest, callable } from "agents";

type ChatState = { messages: { role: string; content: string }[] };

export class ChatAgent extends Agent<Env, ChatState> {
  initialState = { messages: [] };

  @callable()
  async sendMessage(content: string) {
    const messages = [...this.state.messages, { role: "user", content }];
    this.setState({ messages }); // persisted automatically, survives restarts

    const reply = await this.generateReply(messages); // your LLM call
    this.setState({ messages: [...messages, { role: "assistant", content: reply } ]});

    // schedule a follow-up ~24h from now
    await this.schedule(60 * 60 * 24, "sendReminder", { userId: this.name });

    return reply;
  }

  // callback name matches the string passed to schedule()
  async sendReminder(payload: { userId: string }) {
    const reminder = "Hey, following up on our chat yesterday — any update?";
    this.setState({
      messages: [...this.state.messages, { role: "assistant", content: reminder }],
    });
    this.broadcast(JSON.stringify({ type: "reminder", content: reminder }));
    // or push via email/webhook binding here
  }
}

export default {
  fetch: (req: Request, env: Env) =>
    routeAgentRequest(req, env) ?? new Response("Not found", { status: 404 }),
};
