test("owner can mark their todo complete", async () => {
  const t = convexTest(schema, modules);
  const asAlice = t.withIdentity({ subject: "alice" });

  const todoId = await asAlice.mutation(api.todos.create, { text: "Buy milk" });
  await asAlice.mutation(api.todos.complete, { todoId });

  const todo = await t.run((ctx) => ctx.db.get(todoId));
  expect(todo?.completed).toBe(true);
});

test("another user cannot complete someone else's todo", async () => {
  const t = convexTest(schema, modules);
  const asAlice = t.withIdentity({ subject: "alice" });
  const asBob = t.withIdentity({ subject: "bob" });

  const todoId = await asAlice.mutation(api.todos.create, { text: "Buy milk" });

  await expect(
    asBob.mutation(api.todos.complete, { todoId })
  ).rejects.toThrow();

  const todo = await t.run((ctx) => ctx.db.get(todoId));
  expect(todo?.completed).toBe(false); // unchanged
});

