package expo.modules.batterytemperature

import android.content.Context
import android.content.IntentFilter
import android.os.BatteryManager
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition

class ExpoBatteryTemperatureModule : Module() {
  override fun definition() = ModuleDefinition {
    Name("ExpoBatteryTemperature")

    AsyncFunction("getBatteryTemperatureAsync") {
      val context = appContext.reactContext
        ?: throw Exception("React context is unavailable")
      val intent = context.registerReceiver(
        null,
        IntentFilter(android.content.Intent.ACTION_BATTERY_CHANGED)
      )
      val tenthsOfCelsius = intent?.getIntExtra(BatteryManager.EXTRA_TEMPERATURE, -1) ?: -1
      if (tenthsOfCelsius < 0) {
        throw Exception("Battery temperature unavailable")
      }
      tenthsOfCelsius / 10.0
    }
  }
}
