Here's a swipe-to-dismiss card using Gesture Handler's Pan gesture and Reanimated (v2 builder API — swap to `usePanGesture` if you're on RNGH v3):

```tsx
import { useCallback } from 'react';
import { StyleSheet, Text, useWindowDimensions, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, {
  interpolate,
  runOnJS,
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
} from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';

const SWIPE_THRESHOLD = 120;

export function SwipeToDismissCard({
  onDismiss,
  children,
}: {
  onDismiss: () => void;
  children: React.ReactNode;
}) {
  const { width } = useWindowDimensions();
  const translateX = useSharedValue(0);
  const startX = useSharedValue(0);

  const handleDismiss = useCallback(() => onDismiss(), [onDismiss]);

  const pan = Gesture.Pan()
    .activeOffsetX([-10, 10])
    .failOffsetY([-15, 15])
    .onBegin(() => {
      startX.value = translateX.value;
    })
    .onUpdate((e) => {
      translateX.value = startX.value + e.translationX;
    })
    .onEnd((e) => {
      const shouldDismiss =
        Math.abs(translateX.value) > SWIPE_THRESHOLD ||
        Math.abs(e.velocityX) > 800;

      if (shouldDismiss) {
        const direction = translateX.value > 0 ? 1 : -1;
        translateX.value = withTiming(direction * width, { duration: 200 }, () => {
          scheduleOnRN(handleDismiss);
        });
      } else {
        translateX.value = withSpring(0);
      }
    });

  const animatedStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: translateX.value }],
    opacity: interpolate(
      translateX.value,
      [-width, 0, width],
      [0, 1, 0],
    ),
  }));

  return (
    <GestureDetector gesture={pan}>
      <Animated.View style={[styles.card, animatedStyle]}>
        {children}
      </Animated.View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  card: {
    padding: 20,
    borderRadius: 16,
    backgroundColor: 'white',
    shadowOpacity: 0.15,
    shadowRadius: 8,
    elevation: 3,
  },
});
```

Notes:
- Wrap your app root in `GestureHandlerRootView` — `GestureDetector` crashes without it.
- `activeOffsetX`/`failOffsetY` let the pan claim horizontal swipes while letting vertical scrolls pass through.
- `scheduleOnRN` (from `react-native-worklets`) is required to call `onDismiss` since the gesture callback runs on the UI thread — calling it directly would crash.
- Threshold combines distance and velocity so quick flicks dismiss even under the pixel threshold.

