import { Dimensions, StyleSheet, Text, View } from 'react-native';
import { Gesture, GestureDetector } from 'react-native-gesture-handler';
import Animated, {
  useAnimatedStyle,
  useSharedValue,
  withSpring,
  withTiming,
  interpolate,
  Extrapolation,
} from 'react-native-reanimated';
import { scheduleOnRN } from 'react-native-worklets';
import { useMemo } from 'react';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const SWIPE_THRESHOLD = SCREEN_WIDTH * 0.3;

function DismissibleCard({ onDismiss }: { onDismiss: () => void }) {
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);

  const pan = useMemo(
    () =>
      Gesture.Pan()
        .onUpdate((e) => {
          translateX.value = e.translationX;
          translateY.value = e.translationY * 0.2; // subtle vertical drift
        })
        .onEnd((e) => {
          const shouldDismiss =
            Math.abs(translateX.value) > SWIPE_THRESHOLD ||
            Math.abs(e.velocityX) > 800;

          if (shouldDismiss) {
            const direction = translateX.value > 0 ? 1 : -1;
            translateX.value = withTiming(
              direction * SCREEN_WIDTH * 1.5,
              { duration: 250 },
              (finished) => {
                if (finished) scheduleOnRN(onDismiss);
              },
            );
          } else {
            translateX.value = withSpring(0);
            translateY.value = withSpring(0);
          }
        }),
    [onDismiss],
  );

  const animatedStyle = useAnimatedStyle(() => {
    const rotate = interpolate(
      translateX.value,
      [-SCREEN_WIDTH, 0, SCREEN_WIDTH],
      [-15, 0, 15],
      Extrapolation.CLAMP,
    );
    const opacity = interpolate(
      Math.abs(translateX.value),
      [0, SCREEN_WIDTH * 0.5, SCREEN_WIDTH],
      [1, 0.7, 0],
      Extrapolation.CLAMP,
    );

    return {
      opacity,
      transform: [
        { translateX: translateX.value },
        { translateY: translateY.value },
        { rotate: `${rotate}deg` },
      ],
    };
  });

  return (
    <GestureDetector gesture={pan}>
      <Animated.View style={[styles.card, animatedStyle]}>
        <Text style={styles.text}>Swipe me away</Text>
      </Animated.View>
    </GestureDetector>
  );
}

const styles = StyleSheet.create({
  card: {
    width: SCREEN_WIDTH - 40,
    height: 200,
    backgroundColor: '#fff',
    borderRadius: 16,
    alignSelf: 'center',
    justifyContent: 'center',
    alignItems: 'center',
    shadowColor: '#000',
    shadowOpacity: 0.15,
    shadowRadius: 10,
    elevation: 4,
  },
  text: { fontSize: 18, fontWeight: '600' },
});

export default DismissibleCard;
```

Key points:
- `useMemo` on the gesture (v2 API) prevents re-attaching the recognizer every render.
- `withTiming`'s completion callback runs on the UI thread, so `onDismiss` (a JS/React function) is invoked via `scheduleOnRN`, not called directly.
- Rotation and opacity are derived from `translateX` for a natural "flick away" feel.
- Wrap the app root in `<GestureHandlerRootView>` (required, only needs to happen once).

If your `package.json` shows `react-native-gesture-handler` v3, tell me and I'll convert this to the `usePanGesture` hook API instead.
